fn bi_len(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let val = if let Some(input_val) = input {
        input_val
    } else if !args.is_empty() {
        args[0].clone()
    } else {
        return Err(anyhow!("len: requires input or argument"));
    };

    let length = match val {
        Value::Array(ref v) => v.len(),
        Value::Record(ref m) => m.len(),
        Value::Str(ref s) => s.len(),
        _ => {
            return Err(anyhow!(
                "len: requires Array, Record, or String, got {:?}",
                val
            ));
        }
    };

    Ok(Value::Int(length as i64))
}

fn bi_type_of(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let val = if let Some(input_val) = input {
        input_val
    } else if !args.is_empty() {
        args[0].clone()
    } else {
        return Err(anyhow!("type_of: requires input or argument"));
    };

    let type_str = match val {
        Value::Null => "Null",
        Value::Bool(_) => "Bool",
        Value::Int(_) => "Int",
        Value::Float(_) => "Float",
        Value::Str(_) => "String",
        Value::Uri(_) => "Uri",
        Value::Array(_) => "Array",
        Value::Record(_) => "Record",
        Value::Table(_) => "Table",
        Value::Lambda(_) => "Lambda",
        Value::AsyncLambda(_) => "AsyncLambda",
        Value::Future(_) => "Future",
        Value::Builtin(_) => "Builtin",
        Value::Error(_) => "Error",
    };

    Ok(Value::Str(type_str.to_string()))
}

/// is_error(value) - Check if a value is an Error
/// Args:
///   - value: Any value to check
/// Returns: Bool - true if the value is an Error, false otherwise
///
/// Example:
///   let e = throw "something went wrong"
///   is_error(e)  # Returns true
///   is_error(42) # Returns false
fn bi_is_error(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let val = if let Some(input_val) = input {
        input_val
    } else if !args.is_empty() {
        args[0].clone()
    } else {
        return Err(anyhow!("is_error: requires input or argument"));
    };

    let is_err = matches!(val, Value::Error(_));
    Ok(Value::Bool(is_err))
}

// --------------- Debugging Tools ---------------

/// debug(value) - Print value with its type and return the value for chaining
/// Args:
///   - value: Any value to debug
/// Returns: The same value (allows chaining in pipelines)
///
/// Example:
///   let x = debug(42)           # Prints: [DEBUG] Int: 42
///   [1,2,3] | debug | map(...)  # Debug intermediate pipeline values
fn bi_debug(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let val = if let Some(input_val) = input {
        input_val
    } else if !args.is_empty() {
        args[0].clone()
    } else {
        return Err(anyhow!("debug: requires input or argument"));
    };

    let type_str = val.type_name();
    let pretty =
        crate::value::pretty::display_inline(&val, &crate::value::pretty::Theme::default());
    eprintln!("[DEBUG] {}: {}", type_str, pretty);

    // Return the value unchanged for pipeline chaining
    Ok(val)
}

/// assert(condition, message?) - Assert that a condition is true
/// Args:
///   - condition: Boolean condition to check
///   - message: Optional error message (defaults to "assertion failed")
/// Returns: true if assertion passes
/// Throws: Error with message if condition is false
///
/// Example:
///   assert(x > 0, "x must be positive")
///   assert(len(arr) > 0)  # Uses default message
fn bi_assert(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let (cond, msg) = if let Some(input_val) = input {
        // Piped: input is condition, arg 0 is message
        let message = args
            .get(0)
            .and_then(|v| match v {
                Value::Str(s) => Some(s.clone()),
                _ => None,
            })
            .unwrap_or_else(|| "assertion failed".to_string());
        (input_val, message)
    } else if !args.is_empty() {
        // Args: arg 0 is condition, arg 1 is message
        let message = args
            .get(1)
            .and_then(|v| match v {
                Value::Str(s) => Some(s.clone()),
                _ => None,
            })
            .unwrap_or_else(|| "assertion failed".to_string());
        (args[0].clone(), message)
    } else {
        return Err(anyhow!("assert: requires condition argument"));
    };

    // Check if condition is truthy
    let is_truthy = match &cond {
        Value::Bool(b) => *b,
        Value::Null => false,
        Value::Error(_) => false,
        Value::Int(n) => *n != 0,
        Value::Float(f) => *f != 0.0,
        Value::Str(s) => !s.is_empty(),
        Value::Array(arr) => !arr.is_empty(),
        Value::Record(rec) => !rec.is_empty(),
        _ => true,
    };

    if is_truthy {
        Ok(Value::Bool(true))
    } else {
        Ok(Value::Error(msg))
    }
}

/// trace(label, value) - Print a labeled value for tracing and return the value
/// Args:
///   - label: String label to identify the trace point
///   - value: Value to trace (can also be piped)
/// Returns: The value unchanged (allows chaining)
///
/// Example:
///   let result = trace("input", x) | map(fn(n) => n * 2) | trace("output")
///   trace("step1", calculate())
fn bi_trace(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let (label, val) = if let Some(input_val) = input {
        // Piped: input is value, arg 0 is label
        let label = args
            .get(0)
            .and_then(|v| match v {
                Value::Str(s) => Some(s.clone()),
                _ => None,
            })
            .unwrap_or_else(|| "trace".to_string());
        (label, input_val)
    } else if args.len() >= 2 {
        // Two args: label, value
        let label = match &args[0] {
            Value::Str(s) => s.clone(),
            other => format!("{:?}", other),
        };
        (label, args[1].clone())
    } else if args.len() == 1 {
        // One arg: use default label
        ("trace".to_string(), args[0].clone())
    } else {
        return Err(anyhow!("trace: requires at least a value argument"));
    };

    let type_str = val.type_name();
    let pretty =
        crate::value::pretty::display_inline(&val, &crate::value::pretty::Theme::default());
    eprintln!("[TRACE {}] {}: {}", label, type_str, pretty);

    // Return the value unchanged for pipeline chaining
    Ok(val)
}

/// type_assert(value, expected_type) - Assert that a value has the expected type
/// Args:
///   - value: Any value to check
///   - expected_type: String name of expected type ("Int", "String", "Array", etc.)
/// Returns: The value if type matches
/// Throws: Error if type doesn't match
///
/// Example:
///   type_assert(x, "Int")           # Passes if x is an Int
///   data | type_assert("Array")     # Piped: asserts data is Array
fn bi_type_assert(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let (val, expected) = if let Some(input_val) = input {
        // Piped: input is value, arg 0 is expected type
        let expected = args
            .get(0)
            .ok_or_else(|| anyhow!("type_assert: requires expected type argument"))?;
        let expected_str = match expected {
            Value::Str(s) => s.clone(),
            _ => return Err(anyhow!("type_assert: expected type must be a string")),
        };
        (input_val, expected_str)
    } else if args.len() >= 2 {
        // Two args: value, expected_type
        let expected_str = match &args[1] {
            Value::Str(s) => s.clone(),
            _ => return Err(anyhow!("type_assert: expected type must be a string")),
        };
        (args[0].clone(), expected_str)
    } else {
        return Err(anyhow!(
            "type_assert: requires value and expected type arguments"
        ));
    };

    let actual_type = val.type_name();

    // Normalize type names for comparison (case-insensitive)
    let expected_normalized = expected.to_lowercase();
    let actual_normalized = actual_type.to_lowercase();

    if expected_normalized == actual_normalized {
        Ok(val)
    } else {
        Ok(Value::Error(format!(
            "type assertion failed: expected {}, got {}",
            expected, actual_type
        )))
    }
}

/// inspect(value) - Get detailed inspection of a value's structure
/// Args:
///   - value: Any value to inspect
/// Returns: Record with detailed information about the value
///
/// Example:
///   inspect([1,2,3])  # Returns {type: "Array", length: 3, items: [...]}
///   inspect({a: 1})   # Returns {type: "Record", keys: ["a"], values: [...]}
fn bi_inspect(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let val = if let Some(input_val) = input {
        input_val
    } else if !args.is_empty() {
        args[0].clone()
    } else {
        return Err(anyhow!("inspect: requires input or argument"));
    };

    let mut info = BTreeMap::<String, Value>::new();
    info.insert("type".to_string(), Value::Str(val.type_name().to_string()));

    match &val {
        Value::Null => {
            info.insert("value".to_string(), Value::Null);
        }
        Value::Bool(b) => {
            info.insert("value".to_string(), Value::Bool(*b));
        }
        Value::Int(n) => {
            info.insert("value".to_string(), Value::Int(*n));
            info.insert("is_negative".to_string(), Value::Bool(*n < 0));
            info.insert("is_zero".to_string(), Value::Bool(*n == 0));
        }
        Value::Float(f) => {
            info.insert("value".to_string(), Value::Float(*f));
            info.insert("is_nan".to_string(), Value::Bool(f.is_nan()));
            info.insert("is_infinite".to_string(), Value::Bool(f.is_infinite()));
            info.insert("is_negative".to_string(), Value::Bool(*f < 0.0));
        }
        Value::Str(s) => {
            info.insert("value".to_string(), Value::Str(s.clone()));
            info.insert("length".to_string(), Value::Int(s.len() as i64));
            info.insert("is_empty".to_string(), Value::Bool(s.is_empty()));
            info.insert(
                "char_count".to_string(),
                Value::Int(s.chars().count() as i64),
            );
        }
        Value::Uri(u) => {
            info.insert("value".to_string(), Value::Str(u.clone()));
            info.insert("length".to_string(), Value::Int(u.len() as i64));
        }
        Value::Array(arr) => {
            info.insert("length".to_string(), Value::Int(arr.len() as i64));
            info.insert("is_empty".to_string(), Value::Bool(arr.is_empty()));
            if !arr.is_empty() {
                info.insert("first".to_string(), arr[0].clone());
                info.insert("last".to_string(), arr[arr.len() - 1].clone());
                // Collect unique types in the array using a Vec with dedup
                let mut type_strs: Vec<String> =
                    arr.iter().map(|v| v.type_name().to_string()).collect();
                type_strs.sort();
                type_strs.dedup();
                let types: Vec<Value> = type_strs.into_iter().map(Value::Str).collect();
                info.insert("element_types".to_string(), Value::Array(types));
            }
            info.insert("elements".to_string(), Value::Array(arr.clone()));
        }
        Value::Record(rec) => {
            info.insert("length".to_string(), Value::Int(rec.len() as i64));
            info.insert("is_empty".to_string(), Value::Bool(rec.is_empty()));
            info.insert(
                "keys".to_string(),
                Value::Array(rec.keys().map(|k| Value::Str(k.clone())).collect()),
            );
            info.insert(
                "values".to_string(),
                Value::Array(rec.values().cloned().collect()),
            );
            info.insert("entries".to_string(), Value::Record(rec.clone()));
        }
        Value::Table(table) => {
            info.insert("row_count".to_string(), Value::Int(table.rows.len() as i64));
            info.insert("is_empty".to_string(), Value::Bool(table.rows.is_empty()));
            info.insert(
                "columns".to_string(),
                Value::Array(table.schema.iter().map(|k| Value::Str(k.clone())).collect()),
            );
            info.insert(
                "column_count".to_string(),
                Value::Int(table.schema.len() as i64),
            );
        }
        Value::Lambda(lambda) => {
            info.insert(
                "param_count".to_string(),
                Value::Int(lambda.params.len() as i64),
            );
            info.insert(
                "params".to_string(),
                Value::Array(
                    lambda
                        .params
                        .iter()
                        .map(|p| Value::Str(p.clone()))
                        .collect(),
                ),
            );
            info.insert("body".to_string(), Value::Str(format!("{:?}", lambda.body)));
        }
        Value::AsyncLambda(lambda) => {
            info.insert(
                "param_count".to_string(),
                Value::Int(lambda.params.len() as i64),
            );
            info.insert(
                "params".to_string(),
                Value::Array(
                    lambda
                        .params
                        .iter()
                        .map(|p| Value::Str(p.clone()))
                        .collect(),
                ),
            );
            info.insert("body".to_string(), Value::Str(format!("{:?}", lambda.body)));
            info.insert("is_async".to_string(), Value::Bool(true));
        }
        Value::Future(_) => {
            info.insert("pending".to_string(), Value::Bool(true));
            info.insert(
                "description".to_string(),
                Value::Str("Unevaluated future - use await to execute".to_string()),
            );
        }
        Value::Error(msg) => {
            info.insert("message".to_string(), Value::Str(msg.clone()));
            info.insert("is_error".to_string(), Value::Bool(true));
        }
        Value::Builtin(b) => {
            info.insert("name".to_string(), Value::Str(b.name.clone()));
            info.insert("is_builtin".to_string(), Value::Bool(true));
        }
    }

    Ok(Value::Record(info))
}

// --------------- Platform Detection Functions ---------------

/// platform() - Get the current platform name
/// Returns: String - One of "windows", "linux", "macos", "bsd", "ios", "android"
///
/// Example:
///   platform()  # Returns "windows" on Windows
fn bi_platform() -> Result<Value> {
    use crate::os_tools::OperatingSystem;
    let os = OperatingSystem::current();
    let platform_name = match os {
        OperatingSystem::Windows => "windows",
        OperatingSystem::Linux => "linux",
        OperatingSystem::MacOS => "macos",
        OperatingSystem::BSD => "bsd",
        OperatingSystem::iOS => "ios",
        OperatingSystem::Android => "android",
    };
    Ok(Value::Str(platform_name.to_string()))
}

/// is_windows() - Check if running on Windows
/// Returns: Bool
///
/// Example:
///   if is_windows() then "Windows!" else "Not Windows"
fn bi_is_windows() -> Result<Value> {
    Ok(Value::Bool(cfg!(target_os = "windows")))
}

/// is_linux() - Check if running on Linux (excluding Android)
/// Returns: Bool
///
/// Example:
///   if is_linux() then "Linux!" else "Not Linux"
fn bi_is_linux() -> Result<Value> {
    #[cfg(target_os = "linux")]
    {
        // Exclude Android
        let is_android = std::path::Path::new("/system/build.prop").exists();
        Ok(Value::Bool(!is_android))
    }
    #[cfg(not(target_os = "linux"))]
    {
        Ok(Value::Bool(false))
    }
}

/// is_macos() - Check if running on macOS
/// Returns: Bool
///
/// Example:
///   if is_macos() then "macOS!" else "Not macOS"
fn bi_is_macos() -> Result<Value> {
    Ok(Value::Bool(cfg!(target_os = "macos")))
}

/// is_unix() - Check if running on a Unix-like system (Linux, macOS, BSD, etc.)
/// Returns: Bool - true for Linux, macOS, BSD, Android, iOS (Unix-like systems)
///
/// Example:
///   if is_unix() then "/" else "\\"  # Path separator
fn bi_is_unix() -> Result<Value> {
    Ok(Value::Bool(cfg!(unix)))
}

/// is_bsd() - Check if running on BSD (FreeBSD, OpenBSD, NetBSD)
/// Returns: Bool
///
/// Example:
///   if is_bsd() then "BSD!" else "Not BSD"
fn bi_is_bsd() -> Result<Value> {
    let is_bsd = cfg!(target_os = "freebsd")
        || cfg!(target_os = "openbsd")
        || cfg!(target_os = "netbsd")
        || cfg!(target_os = "dragonfly");
    Ok(Value::Bool(is_bsd))
}

/// platform_module(base_path) - Get platform-specific module path
/// Args:
///   - base_path: String - Base module path without extension
/// Returns: String - Platform-specific module path
///
/// Given base_path "mymodule", returns:
///   - "mymodule_windows.ae" on Windows
///   - "mymodule_linux.ae" on Linux
///   - "mymodule_macos.ae" on macOS
///   - etc.
///
/// Example:
///   import platform_module("utils")  # Imports utils_windows.ae on Windows
fn bi_platform_module(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let base_path = if let Some(input_val) = input {
        match input_val {
            Value::Str(s) => s,
            _ => return Err(anyhow!("platform_module: base_path must be a string")),
        }
    } else if !args.is_empty() {
        match &args[0] {
            Value::Str(s) => s.clone(),
            _ => return Err(anyhow!("platform_module: base_path must be a string")),
        }
    } else {
        return Err(anyhow!("platform_module: requires base_path argument"));
    };

    use crate::os_tools::OperatingSystem;
    let os = OperatingSystem::current();
    let platform_suffix = match os {
        OperatingSystem::Windows => "windows",
        OperatingSystem::Linux => "linux",
        OperatingSystem::MacOS => "macos",
        OperatingSystem::BSD => "bsd",
        OperatingSystem::iOS => "ios",
        OperatingSystem::Android => "android",
    };

    // Strip .ae extension if present
    let base = if base_path.ends_with(".ae") {
        &base_path[..base_path.len() - 3]
    } else {
        &base_path
    };

    let module_path = format!("{}_{}.ae", base, platform_suffix);
    Ok(Value::Str(module_path))
}

// --------------- Feature Flag Functions ---------------

/// features() - List all enabled runtime features
/// Returns: Array of String - Names of all enabled features
///
/// Example:
///   features()  # Returns ["ai", "experimental"] if those are enabled
fn bi_features() -> Result<Value> {
    let features = FEATURE_FLAGS
        .read()
        .map_err(|e| anyhow!("features: lock error: {}", e))?;
    let feature_list: Vec<Value> = features.iter().map(|f| Value::Str(f.clone())).collect();
    Ok(Value::Array(feature_list))
}

/// feature_enabled(name) - Check if a runtime feature is enabled
/// Args:
///   - name: String - Feature name to check
/// Returns: Bool - true if the feature is enabled
///
/// Example:
///   feature_enabled("ai")        # Returns true if "ai" feature is enabled
///   has_feature("experimental")  # Alias
fn bi_feature_enabled(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let name = if let Some(input_val) = input {
        match input_val {
            Value::Str(s) => s,
            _ => return Err(anyhow!("feature_enabled: feature name must be a string")),
        }
    } else if !args.is_empty() {
        match &args[0] {
            Value::Str(s) => s.clone(),
            _ => return Err(anyhow!("feature_enabled: feature name must be a string")),
        }
    } else {
        return Err(anyhow!("feature_enabled: requires feature name argument"));
    };

    let features = FEATURE_FLAGS
        .read()
        .map_err(|e| anyhow!("feature_enabled: lock error: {}", e))?;
    Ok(Value::Bool(features.contains(&name)))
}

/// feature_enable(name) - Enable a runtime feature
/// Args:
///   - name: String - Feature name to enable
/// Returns: Bool - true (always succeeds)
///
/// Example:
///   feature_enable("experimental")
fn bi_feature_enable(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let name = if let Some(input_val) = input {
        match input_val {
            Value::Str(s) => s,
            _ => return Err(anyhow!("feature_enable: feature name must be a string")),
        }
    } else if !args.is_empty() {
        match &args[0] {
            Value::Str(s) => s.clone(),
            _ => return Err(anyhow!("feature_enable: feature name must be a string")),
        }
    } else {
        return Err(anyhow!("feature_enable: requires feature name argument"));
    };

    let mut features = FEATURE_FLAGS
        .write()
        .map_err(|e| anyhow!("feature_enable: lock error: {}", e))?;
    features.insert(name);
    Ok(Value::Bool(true))
}

/// feature_disable(name) - Disable a runtime feature
/// Args:
///   - name: String - Feature name to disable
/// Returns: Bool - true if the feature was disabled, false if it wasn't enabled
///
/// Example:
///   feature_disable("experimental")
fn bi_feature_disable(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let name = if let Some(input_val) = input {
        match input_val {
            Value::Str(s) => s,
            _ => return Err(anyhow!("feature_disable: feature name must be a string")),
        }
    } else if !args.is_empty() {
        match &args[0] {
            Value::Str(s) => s.clone(),
            _ => return Err(anyhow!("feature_disable: feature name must be a string")),
        }
    } else {
        return Err(anyhow!("feature_disable: requires feature name argument"));
    };

    let mut features = FEATURE_FLAGS
        .write()
        .map_err(|e| anyhow!("feature_disable: lock error: {}", e))?;
    let removed = features.remove(&name);
    Ok(Value::Bool(removed))
}

/// feature_set(name, enabled) - Set a runtime feature to enabled or disabled
/// Args:
///   - name: String - Feature name
///   - enabled: Bool - true to enable, false to disable
/// Returns: Bool - true (always succeeds)
///
/// Example:
///   feature_set("ai", true)       # Enable "ai" feature
///   feature_set("debug", false)   # Disable "debug" feature
fn bi_feature_set(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let (name, enabled) = if let Some(input_val) = input {
        // Piped: input is name, arg 0 is enabled
        let name = match input_val {
            Value::Str(s) => s,
            _ => return Err(anyhow!("feature_set: feature name must be a string")),
        };
        let enabled = args
            .get(0)
            .ok_or_else(|| anyhow!("feature_set: requires enabled argument"))?;
        let enabled = match enabled {
            Value::Bool(b) => *b,
            _ => return Err(anyhow!("feature_set: enabled must be a boolean")),
        };
        (name, enabled)
    } else if args.len() >= 2 {
        // Two args: name, enabled
        let name = match &args[0] {
            Value::Str(s) => s.clone(),
            _ => return Err(anyhow!("feature_set: feature name must be a string")),
        };
        let enabled = match &args[1] {
            Value::Bool(b) => *b,
            _ => return Err(anyhow!("feature_set: enabled must be a boolean")),
        };
        (name, enabled)
    } else {
        return Err(anyhow!("feature_set: requires name and enabled arguments"));
    };

    let mut features = FEATURE_FLAGS
        .write()
        .map_err(|e| anyhow!("feature_set: lock error: {}", e))?;
    if enabled {
        features.insert(name);
    } else {
        features.remove(&name);
    }
    Ok(Value::Bool(true))
}

// ===================== Distributed Computing Builtins =====================

/// cluster_create(name) - Create a new compute cluster
/// Args:
///   - name: String - Cluster name (optional, defaults to "default")
/// Returns: Record with cluster info
fn bi_cluster_create(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let name = input
        .or_else(|| args.first().cloned())
        .map(|v| match v {
            Value::Str(s) => s,
            _ => "default".to_string(),
        })
        .unwrap_or_else(|| "default".to_string());

    let mut record = BTreeMap::new();
    record.insert("name".to_string(), Value::Str(name.clone()));
    record.insert("status".to_string(), Value::Str("created".to_string()));
    record.insert("node_count".to_string(), Value::Int(0));
    record.insert(
        "created_at".to_string(),
        Value::Str(chrono::Utc::now().to_rfc3339()),
    );

    Ok(Value::Record(record))
}

/// cluster_add_node(id, address, capabilities?) - Add a node to the cluster
/// Args:
///   - id: String - Node identifier
///   - address: String - Node address (e.g., "192.168.1.10:8080")
///   - capabilities: Array - Optional list of capabilities
/// Returns: Record with node info
fn bi_cluster_add_node(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let (id, address) = if let Some(Value::Record(rec)) = input.clone() {
        // Record input: {id: "...", address: "..."}
        let id = rec
            .get("id")
            .map(|v| v.to_display_string())
            .ok_or_else(|| anyhow!("cluster_add_node: missing 'id' in record"))?;
        let address = rec
            .get("address")
            .map(|v| v.to_display_string())
            .ok_or_else(|| anyhow!("cluster_add_node: missing 'address' in record"))?;
        (id, address)
    } else if args.len() >= 2 {
        let id = args[0].to_display_string();
        let address = args[1].to_display_string();
        (id, address)
    } else {
        return Err(anyhow!(
            "cluster_add_node: requires id and address arguments"
        ));
    };

    let capabilities = if args.len() >= 3 {
        match &args[2] {
            Value::Array(arr) => arr.iter().map(|v| v.to_display_string()).collect(),
            _ => vec![],
        }
    } else {
        vec!["compute".to_string(), "storage".to_string()]
    };

    let node = ClusterNode {
        id: id.clone(),
        address: address.clone(),
        capabilities: capabilities.clone(),
        status: NodeStatus::Online,
        load: 0.0,
        last_heartbeat: std::time::Instant::now(),
    };

    let mut nodes = CLUSTER_NODES
        .write()
        .map_err(|e| anyhow!("cluster_add_node: lock error: {}", e))?;
    nodes.insert(id.clone(), node);

    let mut record = BTreeMap::new();
    record.insert("id".to_string(), Value::Str(id));
    record.insert("address".to_string(), Value::Str(address));
    record.insert(
        "capabilities".to_string(),
        Value::Array(capabilities.into_iter().map(Value::Str).collect()),
    );
    record.insert("status".to_string(), Value::Str("online".to_string()));

    Ok(Value::Record(record))
}

/// cluster_remove_node(id) - Remove a node from the cluster
fn bi_cluster_remove_node(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let id = input
        .or_else(|| args.first().cloned())
        .map(|v| v.to_display_string())
        .ok_or_else(|| anyhow!("cluster_remove_node: requires node id"))?;

    let mut nodes = CLUSTER_NODES
        .write()
        .map_err(|e| anyhow!("cluster_remove_node: lock error: {}", e))?;

    let removed = nodes.remove(&id).is_some();
    Ok(Value::Bool(removed))
}

/// cluster_status() - Get cluster status
fn bi_cluster_status(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let _ = args;
    let nodes = CLUSTER_NODES
        .read()
        .map_err(|e| anyhow!("cluster_status: lock error: {}", e))?;

    let jobs = DISTRIBUTED_JOBS
        .read()
        .map_err(|e| anyhow!("cluster_status: lock error: {}", e))?;

    let online_count = nodes
        .values()
        .filter(|n| n.status == NodeStatus::Online)
        .count();
    let busy_count = nodes
        .values()
        .filter(|n| n.status == NodeStatus::Busy)
        .count();
    let pending_jobs = jobs
        .values()
        .filter(|j| j.status == JobStatus::Pending)
        .count();
    let running_jobs = jobs
        .values()
        .filter(|j| j.status == JobStatus::Running)
        .count();
    let avg_load: f32 = if nodes.is_empty() {
        0.0
    } else {
        nodes.values().map(|n| n.load).sum::<f32>() / nodes.len() as f32
    };

    let mut record = BTreeMap::new();
    record.insert("total_nodes".to_string(), Value::Int(nodes.len() as i64));
    record.insert("online_nodes".to_string(), Value::Int(online_count as i64));
    record.insert("busy_nodes".to_string(), Value::Int(busy_count as i64));
    record.insert("total_jobs".to_string(), Value::Int(jobs.len() as i64));
    record.insert("pending_jobs".to_string(), Value::Int(pending_jobs as i64));
    record.insert("running_jobs".to_string(), Value::Int(running_jobs as i64));
    record.insert("average_load".to_string(), Value::Float(avg_load as f64));

    Ok(Value::Record(record))
}

/// cluster_nodes() - List all nodes in the cluster
fn bi_cluster_nodes(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let _ = args;
    let nodes = CLUSTER_NODES
        .read()
        .map_err(|e| anyhow!("cluster_nodes: lock error: {}", e))?;

    let node_list: Vec<Value> = nodes
        .values()
        .map(|node| {
            let mut record = BTreeMap::new();
            record.insert("id".to_string(), Value::Str(node.id.clone()));
            record.insert("address".to_string(), Value::Str(node.address.clone()));
            record.insert(
                "status".to_string(),
                Value::Str(node.status.as_str().to_string()),
            );
            record.insert("load".to_string(), Value::Float(node.load as f64));
            record.insert(
                "capabilities".to_string(),
                Value::Array(
                    node.capabilities
                        .iter()
                        .map(|c| Value::Str(c.clone()))
                        .collect(),
                ),
            );
            Value::Record(record)
        })
        .collect();

    Ok(Value::Array(node_list))
}

/// job_submit(name, task, priority?) - Submit a job to the cluster
fn bi_job_submit(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let (name, task) = if let Some(Value::Record(rec)) = input.clone() {
        let name = rec
            .get("name")
            .map(|v| v.to_display_string())
            .ok_or_else(|| anyhow!("job_submit: missing 'name'"))?;
        let task = rec
            .get("task")
            .map(|v| v.to_display_string())
            .ok_or_else(|| anyhow!("job_submit: missing 'task'"))?;
        (name, task)
    } else if args.len() >= 2 {
        (args[0].to_display_string(), args[1].to_display_string())
    } else {
        return Err(anyhow!("job_submit: requires name and task"));
    };

    let priority = args
        .get(2)
        .map(|v| match v {
            Value::Int(i) => *i as i32,
            _ => 0,
        })
        .unwrap_or(0);

    let job_id = format!(
        "job_{}",
        uuid::Uuid::new_v4().to_string().split('-').next().unwrap()
    );

    let job = DistributedJob {
        id: job_id.clone(),
        name,
        task,
        node_id: None,
        status: JobStatus::Pending,
        priority,
        created_at: std::time::Instant::now(),
        started_at: None,
        completed_at: None,
    };

    let mut jobs = DISTRIBUTED_JOBS
        .write()
        .map_err(|e| anyhow!("job_submit: lock error: {}", e))?;
    jobs.insert(job_id.clone(), job);

    let mut record = BTreeMap::new();
    record.insert("job_id".to_string(), Value::Str(job_id));
    record.insert("status".to_string(), Value::Str("pending".to_string()));

    Ok(Value::Record(record))
}

/// job_status(job_id) - Get the status of a job
fn bi_job_status(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let job_id = input
        .or_else(|| args.first().cloned())
        .map(|v| v.to_display_string())
        .ok_or_else(|| anyhow!("job_status: requires job_id"))?;

    let jobs = DISTRIBUTED_JOBS
        .read()
        .map_err(|e| anyhow!("job_status: lock error: {}", e))?;

    let job = jobs
        .get(&job_id)
        .ok_or_else(|| anyhow!("job_status: job '{}' not found", job_id))?;

    let mut record = BTreeMap::new();
    record.insert("job_id".to_string(), Value::Str(job.id.clone()));
    record.insert("name".to_string(), Value::Str(job.name.clone()));
    record.insert(
        "status".to_string(),
        Value::Str(job.status.as_str().to_string()),
    );
    record.insert("priority".to_string(), Value::Int(job.priority as i64));
    if let Some(node_id) = &job.node_id {
        record.insert("node_id".to_string(), Value::Str(node_id.clone()));
    }

    Ok(Value::Record(record))
}

/// job_cancel(job_id) - Cancel a pending or running job
fn bi_job_cancel(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let job_id = input
        .or_else(|| args.first().cloned())
        .map(|v| v.to_display_string())
        .ok_or_else(|| anyhow!("job_cancel: requires job_id"))?;

    let mut jobs = DISTRIBUTED_JOBS
        .write()
        .map_err(|e| anyhow!("job_cancel: lock error: {}", e))?;

    if let Some(job) = jobs.get_mut(&job_id) {
        match job.status {
            JobStatus::Pending | JobStatus::Running => {
                job.status = JobStatus::Cancelled;
                Ok(Value::Bool(true))
            }
            _ => Ok(Value::Bool(false)),
        }
    } else {
        Err(anyhow!("job_cancel: job '{}' not found", job_id))
    }
}

/// job_results(job_id) - Get the results of a completed job
fn bi_job_results(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let job_id = input
        .or_else(|| args.first().cloned())
        .map(|v| v.to_display_string())
        .ok_or_else(|| anyhow!("job_results: requires job_id"))?;

    let results = JOB_RESULTS
        .read()
        .map_err(|e| anyhow!("job_results: lock error: {}", e))?;

    if let Some(result_values) = results.get(&job_id) {
        Ok(Value::Array(result_values.clone()))
    } else {
        Ok(Value::Array(vec![]))
    }
}

