fn bi_svc_list(_args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    #[cfg(target_os = "windows")]
    {
        let output = std::process::Command::new("powershell")
            .args([
                "-Command",
                "Get-Service | Select-Object Name,DisplayName,Status | ConvertTo-Json",
            ])
            .output()?;
        if output.status.success() {
            let json_str = String::from_utf8_lossy(&output.stdout);
            if let Ok(json) = serde_json::from_str::<serde_json::Value>(&json_str) {
                return Ok(json_to_value(json));
            }
        }
    }
    #[cfg(target_os = "linux")]
    {
        let output = std::process::Command::new("systemctl")
            .args([
                "list-units",
                "--type=service",
                "--no-pager",
                "--output=json",
            ])
            .output()?;
        if output.status.success() {
            let json_str = String::from_utf8_lossy(&output.stdout);
            if let Ok(json) = serde_json::from_str::<serde_json::Value>(&json_str) {
                return Ok(json_to_value(json));
            }
        }
    }
    Ok(Value::Array(vec![]))
}

fn bi_svc_status(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let name = match args.first() {
        Some(Value::Str(s)) => s.clone(),
        _ => return Ok(Value::Null),
    };

    #[cfg(target_os = "windows")]
    {
        let output = std::process::Command::new("powershell")
            .args([
                "-Command",
                &format!(
                    "Get-Service '{}' | Select-Object Name,Status | ConvertTo-Json",
                    name
                ),
            ])
            .output()?;
        if output.status.success() {
            let json_str = String::from_utf8_lossy(&output.stdout);
            if let Ok(json) = serde_json::from_str::<serde_json::Value>(&json_str) {
                return Ok(json_to_value(json));
            }
        }
    }
    #[cfg(target_os = "linux")]
    {
        let output = std::process::Command::new("systemctl")
            .args(["status", &name])
            .output()?;
        return Ok(Value::Str(
            String::from_utf8_lossy(&output.stdout).to_string(),
        ));
    }
    Ok(Value::Null)
}

