// =====================================================================
// ROBUST FILE EDITING BUILTINS (for AI agents)
// =====================================================================
// These functions provide structured, atomic file editing that avoids
// shell quoting/escaping issues that plague BASH and PowerShell.
// AI agents can safely manipulate multi-line text without worrying about
// special characters, newlines, or encoding problems.
// =====================================================================

/// file_write(path, content) - Write content to a file (creates or overwrites)
/// This is the foundation for safe file writing without shell escaping issues.
/// Usage: file_write("config.txt", "line1\nline2\nline3")
///        content | file_write("output.txt")
fn bi_file_write(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    if args.is_empty() {
        return Err(anyhow!("file_write requires a file path"));
    }

    let path = match &args[0] {
        Value::Str(s) => s.clone(),
        _ => return Err(anyhow!("file_write: path must be a string")),
    };

    // Get content from args or pipeline input
    let content = if args.len() > 1 {
        match &args[1] {
            Value::Str(s) => s.clone(),
            Value::Array(arr) => arr
                .iter()
                .map(|v| match v {
                    Value::Str(s) => s.clone(),
                    other => format!("{:?}", other),
                })
                .collect::<Vec<_>>()
                .join("\n"),
            other => format!("{:?}", other),
        }
    } else {
        match input {
            Some(Value::Str(s)) => s,
            Some(Value::Array(arr)) => arr
                .iter()
                .map(|v| match v {
                    Value::Str(s) => s.clone(),
                    other => format!("{:?}", other),
                })
                .collect::<Vec<_>>()
                .join("\n"),
            Some(other) => format!("{:?}", other),
            None => return Err(anyhow!("file_write requires content to write")),
        }
    };

    // Write atomically: write to temp file, then rename
    let parent = std::path::Path::new(&path).parent();
    let temp_path = match parent {
        Some(p) if p.exists() => {
            let temp_name = format!(".aether_tmp_{}", std::process::id());
            p.join(temp_name).to_string_lossy().to_string()
        }
        _ => format!(".aether_tmp_{}", std::process::id()),
    };

    // Write to temp file
    fs::write(&temp_path, &content)
        .with_context(|| format!("file_write: failed to write temp file '{}'", temp_path))?;

    // Rename to final destination (atomic on most filesystems)
    fs::rename(&temp_path, &path)
        .or_else(|_| {
            // Fallback: copy and delete (for cross-device moves)
            fs::copy(&temp_path, &path)?;
            fs::remove_file(&temp_path)?;
            Ok::<(), std::io::Error>(())
        })
        .with_context(|| format!("file_write: failed to write to '{}'", path))?;

    let mut result = BTreeMap::new();
    result.insert("path".to_string(), Value::Str(path));
    result.insert("bytes".to_string(), Value::Int(content.len() as i64));
    result.insert(
        "lines".to_string(),
        Value::Int(content.lines().count() as i64),
    );
    result.insert("success".to_string(), Value::Bool(true));

    Ok(Value::Record(result))
}

/// file_append(path, content) - Append content to a file
/// Usage: file_append("log.txt", "New log entry\n")
///        new_lines | file_append("data.txt")
fn bi_file_append(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    if args.is_empty() {
        return Err(anyhow!("file_append requires a file path"));
    }

    let path = match &args[0] {
        Value::Str(s) => s.clone(),
        _ => return Err(anyhow!("file_append: path must be a string")),
    };

    // Get content from args or pipeline input
    let content = if args.len() > 1 {
        match &args[1] {
            Value::Str(s) => s.clone(),
            Value::Array(arr) => arr
                .iter()
                .map(|v| match v {
                    Value::Str(s) => s.clone(),
                    other => format!("{:?}", other),
                })
                .collect::<Vec<_>>()
                .join("\n"),
            other => format!("{:?}", other),
        }
    } else {
        match input {
            Some(Value::Str(s)) => s,
            Some(Value::Array(arr)) => arr
                .iter()
                .map(|v| match v {
                    Value::Str(s) => s.clone(),
                    other => format!("{:?}", other),
                })
                .collect::<Vec<_>>()
                .join("\n"),
            Some(other) => format!("{:?}", other),
            None => return Err(anyhow!("file_append requires content to append")),
        }
    };

    use std::io::Write;
    let mut file = std::fs::OpenOptions::new()
        .create(true)
        .append(true)
        .open(&path)
        .with_context(|| format!("file_append: failed to open '{}'", path))?;

    file.write_all(content.as_bytes())
        .with_context(|| format!("file_append: failed to write to '{}'", path))?;

    let mut result = BTreeMap::new();
    result.insert("path".to_string(), Value::Str(path));
    result.insert(
        "bytes_appended".to_string(),
        Value::Int(content.len() as i64),
    );
    result.insert("success".to_string(), Value::Bool(true));

    Ok(Value::Record(result))
}

/// file_patch(path, patches) - Apply multiple search/replace operations atomically
/// Patches is an array of records: [{find: "old", replace: "new"}, ...]
/// Usage: file_patch("config.txt", [{find: "DEBUG=0", replace: "DEBUG=1"}])
fn bi_file_patch(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    if args.is_empty() {
        return Err(anyhow!("file_patch requires a file path"));
    }

    let path = match &args[0] {
        Value::Str(s) => s.clone(),
        _ => return Err(anyhow!("file_patch: path must be a string")),
    };

    let patches = if args.len() > 1 {
        match &args[1] {
            Value::Array(arr) => arr.clone(),
            Value::Record(r) => vec![Value::Record(r.clone())],
            _ => return Err(anyhow!("file_patch: patches must be an array of records")),
        }
    } else {
        match input {
            Some(Value::Array(arr)) => arr,
            Some(Value::Record(r)) => vec![Value::Record(r)],
            _ => return Err(anyhow!("file_patch: patches must be provided")),
        }
    };

    // Read current content
    let mut content = fs::read_to_string(&path)
        .with_context(|| format!("file_patch: failed to read '{}'", path))?;

    let mut applied = Vec::new();
    let mut failed = Vec::new();

    for (i, patch) in patches.iter().enumerate() {
        let record = match patch {
            Value::Record(r) => r,
            _ => {
                failed.push(Value::Str(format!("patch {}: not a record", i)));
                continue;
            }
        };

        let find_str = match record
            .get("find")
            .or(record.get("old"))
            .or(record.get("search"))
        {
            Some(Value::Str(s)) => s.clone(),
            _ => {
                failed.push(Value::Str(format!("patch {}: missing 'find' string", i)));
                continue;
            }
        };

        let replace_str = match record
            .get("replace")
            .or(record.get("new"))
            .or(record.get("with"))
        {
            Some(Value::Str(s)) => s.clone(),
            _ => {
                failed.push(Value::Str(format!("patch {}: missing 'replace' string", i)));
                continue;
            }
        };

        if content.contains(&find_str) {
            let count = content.matches(&find_str).count();
            content = content.replace(&find_str, &replace_str);

            let mut patch_result = BTreeMap::new();
            patch_result.insert("find".to_string(), Value::Str(find_str));
            patch_result.insert("replace".to_string(), Value::Str(replace_str));
            patch_result.insert("count".to_string(), Value::Int(count as i64));
            applied.push(Value::Record(patch_result));
        } else {
            failed.push(Value::Str(format!(
                "patch {}: '{}' not found",
                i,
                if find_str.len() > 40 {
                    format!("{}...", &find_str[..40])
                } else {
                    find_str
                }
            )));
        }
    }

    // Write back atomically
    let temp_path = format!("{}.aether_tmp", path);
    fs::write(&temp_path, &content)?;
    fs::rename(&temp_path, &path)?;

    let mut result = BTreeMap::new();
    result.insert("path".to_string(), Value::Str(path));
    result.insert("applied".to_string(), Value::Array(applied.clone()));
    result.insert("failed".to_string(), Value::Array(failed.clone()));
    result.insert("success".to_string(), Value::Bool(failed.is_empty()));
    result.insert(
        "patches_applied".to_string(),
        Value::Int(applied.len() as i64),
    );
    result.insert(
        "patches_failed".to_string(),
        Value::Int(failed.len() as i64),
    );

    Ok(Value::Record(result))
}

/// file_replace(path, old_text, new_text) - Simple string replacement in a file
/// Usage: file_replace("config.txt", "old_value", "new_value")
fn bi_file_replace(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    if args.len() < 3 {
        return Err(anyhow!(
            "file_replace requires path, old_text, and new_text"
        ));
    }

    let path = match &args[0] {
        Value::Str(s) => s.clone(),
        _ => return Err(anyhow!("file_replace: path must be a string")),
    };

    let old_text = match &args[1] {
        Value::Str(s) => s.clone(),
        _ => return Err(anyhow!("file_replace: old_text must be a string")),
    };

    let new_text = match &args[2] {
        Value::Str(s) => s.clone(),
        _ => return Err(anyhow!("file_replace: new_text must be a string")),
    };

    let mut patch = BTreeMap::new();
    patch.insert("find".to_string(), Value::Str(old_text));
    patch.insert("replace".to_string(), Value::Str(new_text));

    bi_file_patch(
        vec![Value::Str(path), Value::Array(vec![Value::Record(patch)])],
        None,
    )
}

/// file_insert(path, position, content) - Insert content at a specific position
fn bi_file_insert(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    if args.len() < 2 {
        return Err(anyhow!("file_insert requires path and position"));
    }

    let path = match &args[0] {
        Value::Str(s) => s.clone(),
        _ => return Err(anyhow!("file_insert: path must be a string")),
    };

    let content = if args.len() > 2 {
        match &args[2] {
            Value::Str(s) => s.clone(),
            Value::Array(arr) => arr
                .iter()
                .map(|v| match v {
                    Value::Str(s) => s.clone(),
                    other => format!("{:?}", other),
                })
                .collect::<Vec<_>>()
                .join("\n"),
            other => format!("{:?}", other),
        }
    } else {
        match input {
            Some(Value::Str(s)) => s,
            Some(Value::Array(arr)) => arr
                .iter()
                .map(|v| match v {
                    Value::Str(s) => s.clone(),
                    other => format!("{:?}", other),
                })
                .collect::<Vec<_>>()
                .join("\n"),
            Some(other) => format!("{:?}", other),
            None => return Err(anyhow!("file_insert requires content to insert")),
        }
    };

    let mut file_content = fs::read_to_string(&path)
        .with_context(|| format!("file_insert: failed to read '{}'", path))?;

    let mut lines: Vec<String> = file_content.lines().map(|s| s.to_string()).collect();
    let insert_lines: Vec<String> = content.lines().map(|s| s.to_string()).collect();
    let insert_pos: usize;
    let mut pattern_found = true;

    match &args[1] {
        Value::Int(line_num) => {
            let line = (*line_num).max(1) as usize;
            insert_pos = (line - 1).min(lines.len());
        }
        Value::Str(pos) => match pos.as_str() {
            "start" | "beginning" | "top" => insert_pos = 0,
            "end" | "bottom" | "append" => insert_pos = lines.len(),
            _ => {
                if let Some(idx) = lines.iter().position(|l| l.contains(pos)) {
                    insert_pos = idx + 1;
                } else {
                    pattern_found = false;
                    insert_pos = lines.len();
                }
            }
        },
        Value::Record(r) => {
            if let Some(Value::Str(after_pattern)) = r.get("after") {
                if let Some(idx) = lines.iter().position(|l| l.contains(after_pattern)) {
                    insert_pos = idx + 1;
                } else {
                    pattern_found = false;
                    insert_pos = lines.len();
                }
            } else if let Some(Value::Str(before_pattern)) = r.get("before") {
                if let Some(idx) = lines.iter().position(|l| l.contains(before_pattern)) {
                    insert_pos = idx;
                } else {
                    pattern_found = false;
                    insert_pos = 0;
                }
            } else if let Some(Value::Int(line)) = r.get("line") {
                insert_pos = ((*line).max(1) as usize - 1).min(lines.len());
            } else {
                return Err(anyhow!(
                    "file_insert: position record must have 'after', 'before', or 'line' key"
                ));
            }
        }
        _ => {
            return Err(anyhow!(
                "file_insert: position must be a line number, string, or record"
            ))
        }
    }

    for (i, line) in insert_lines.iter().enumerate() {
        lines.insert(insert_pos + i, line.clone());
    }

    file_content = lines.join("\n");
    if !file_content.ends_with('\n') {
        file_content.push('\n');
    }

    let temp_path = format!("{}.aether_tmp", path);
    fs::write(&temp_path, &file_content)?;
    fs::rename(&temp_path, &path)?;

    let mut result = BTreeMap::new();
    result.insert("path".to_string(), Value::Str(path));
    result.insert(
        "lines_inserted".to_string(),
        Value::Int(insert_lines.len() as i64),
    );
    result.insert("at_line".to_string(), Value::Int((insert_pos + 1) as i64));
    result.insert("pattern_found".to_string(), Value::Bool(pattern_found));
    result.insert("success".to_string(), Value::Bool(true));

    Ok(Value::Record(result))
}

/// file_delete_lines(path, start, end?) - Delete lines from a file
fn bi_file_delete_lines(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    if args.len() < 2 {
        return Err(anyhow!(
            "file_delete_lines requires path and line specification"
        ));
    }

    let path = match &args[0] {
        Value::Str(s) => s.clone(),
        _ => return Err(anyhow!("file_delete_lines: path must be a string")),
    };

    let content = fs::read_to_string(&path)
        .with_context(|| format!("file_delete_lines: failed to read '{}'", path))?;

    let lines: Vec<&str> = content.lines().collect();
    let original_count = lines.len();
    let mut keep: Vec<bool> = vec![true; lines.len()];

    match &args[1] {
        Value::Int(start_line) => {
            let start = (*start_line).max(1) as usize - 1;
            let end = if args.len() > 2 {
                match &args[2] {
                    Value::Int(e) => (*e).max(1) as usize - 1,
                    _ => start,
                }
            } else {
                start
            };

            for i in start..=end.min(lines.len() - 1) {
                keep[i] = false;
            }
        }
        Value::Record(r) => {
            if let Some(Value::Str(pattern)) =
                r.get("matching").or(r.get("contains")).or(r.get("pattern"))
            {
                for (i, line) in lines.iter().enumerate() {
                    if line.contains(pattern) {
                        keep[i] = false;
                    }
                }
            } else if let Some(Value::Str(exact)) = r.get("exact") {
                for (i, line) in lines.iter().enumerate() {
                    if *line == exact {
                        keep[i] = false;
                    }
                }
            } else {
                return Err(anyhow!(
                    "file_delete_lines: record must have 'matching', 'contains', or 'exact' key"
                ));
            }
        }
        _ => {
            return Err(anyhow!(
                "file_delete_lines: second argument must be line number or record"
            ))
        }
    }

    let new_lines: Vec<&str> = lines
        .into_iter()
        .enumerate()
        .filter(|(i, _)| keep[*i])
        .map(|(_, line)| line)
        .collect();

    let deleted_count = original_count - new_lines.len();
    let mut new_content = new_lines.join("\n");
    if !new_content.is_empty() {
        new_content.push('\n');
    }

    let temp_path = format!("{}.aether_tmp", path);
    fs::write(&temp_path, &new_content)?;
    fs::rename(&temp_path, &path)?;

    let mut result = BTreeMap::new();
    result.insert("path".to_string(), Value::Str(path));
    result.insert(
        "lines_deleted".to_string(),
        Value::Int(deleted_count as i64),
    );
    result.insert(
        "lines_remaining".to_string(),
        Value::Int(new_lines.len() as i64),
    );
    result.insert("success".to_string(), Value::Bool(true));

    Ok(Value::Record(result))
}

/// file_edit(path, edits) - Apply structured edits to a file
fn bi_file_edit(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    if args.is_empty() {
        return Err(anyhow!("file_edit requires a file path"));
    }

    let path = match &args[0] {
        Value::Str(s) => s.clone(),
        _ => return Err(anyhow!("file_edit: path must be a string")),
    };

    let edits = if args.len() > 1 {
        match &args[1] {
            Value::Array(arr) => arr.clone(),
            Value::Record(r) => vec![Value::Record(r.clone())],
            _ => {
                return Err(anyhow!(
                    "file_edit: edits must be an array of edit operations"
                ))
            }
        }
    } else {
        match input {
            Some(Value::Array(arr)) => arr,
            Some(Value::Record(r)) => vec![Value::Record(r)],
            _ => return Err(anyhow!("file_edit: edits must be provided")),
        }
    };

    let content = fs::read_to_string(&path)
        .with_context(|| format!("file_edit: failed to read '{}'", path))?;

    let mut lines: Vec<String> = content.lines().map(|s| s.to_string()).collect();
    let mut applied = Vec::new();
    let mut failed = Vec::new();

    // Sort edits by line number in reverse order
    let mut sorted_edits: Vec<(usize, Value)> = edits.into_iter().enumerate().collect();
    sorted_edits.sort_by(|a, b| {
        let get_line = |v: &Value| -> i64 {
            if let Value::Record(r) = v {
                r.get("start_line")
                    .or(r.get("line"))
                    .and_then(|v| match v {
                        Value::Int(n) => Some(*n),
                        _ => None,
                    })
                    .unwrap_or(0)
            } else {
                0
            }
        };
        get_line(&b.1).cmp(&get_line(&a.1))
    });

    for (idx, edit) in sorted_edits {
        let record = match &edit {
            Value::Record(r) => r,
            _ => {
                failed.push(Value::Str(format!("edit {}: not a record", idx)));
                continue;
            }
        };

        let op = match record.get("op").or(record.get("operation")) {
            Some(Value::Str(s)) => s.as_str(),
            _ => {
                failed.push(Value::Str(format!("edit {}: missing 'op' field", idx)));
                continue;
            }
        };

        match op {
            "replace_range" | "replace" => {
                let start_line = match record.get("start_line").or(record.get("line")) {
                    Some(Value::Int(n)) => (*n).max(1) as usize - 1,
                    _ => {
                        failed.push(Value::Str(format!("edit {}: missing start_line", idx)));
                        continue;
                    }
                };
                let end_line = match record.get("end_line") {
                    Some(Value::Int(n)) => (*n).max(1) as usize - 1,
                    _ => start_line,
                };
                let new_content = match record.get("content").or(record.get("text")) {
                    Some(Value::Str(s)) => s.clone(),
                    _ => String::new(),
                };

                if start_line < lines.len() {
                    let end = end_line.min(lines.len() - 1);
                    let new_lines: Vec<String> =
                        new_content.lines().map(|s| s.to_string()).collect();

                    lines.drain(start_line..=end);
                    for (i, line) in new_lines.into_iter().enumerate() {
                        lines.insert(start_line + i, line);
                    }

                    let mut result = BTreeMap::new();
                    result.insert("op".to_string(), Value::Str("replace_range".to_string()));
                    result.insert(
                        "start_line".to_string(),
                        Value::Int((start_line + 1) as i64),
                    );
                    result.insert("end_line".to_string(), Value::Int((end + 1) as i64));
                    applied.push(Value::Record(result));
                } else {
                    failed.push(Value::Str(format!(
                        "edit {}: line {} out of range",
                        idx,
                        start_line + 1
                    )));
                }
            }
            "insert_at" | "insert" => {
                let line = match record.get("line") {
                    Some(Value::Int(n)) => (*n).max(1) as usize - 1,
                    _ => {
                        failed.push(Value::Str(format!("edit {}: missing line", idx)));
                        continue;
                    }
                };
                let new_content = match record.get("content").or(record.get("text")) {
                    Some(Value::Str(s)) => s.clone(),
                    _ => String::new(),
                };

                let insert_pos = line.min(lines.len());
                let new_lines: Vec<String> = new_content.lines().map(|s| s.to_string()).collect();

                for (i, new_line) in new_lines.iter().enumerate() {
                    lines.insert(insert_pos + i, new_line.clone());
                }

                let mut result = BTreeMap::new();
                result.insert("op".to_string(), Value::Str("insert_at".to_string()));
                result.insert("line".to_string(), Value::Int((insert_pos + 1) as i64));
                result.insert(
                    "lines_inserted".to_string(),
                    Value::Int(new_lines.len() as i64),
                );
                applied.push(Value::Record(result));
            }
            "delete_range" | "delete" => {
                let start_line = match record.get("start_line").or(record.get("line")) {
                    Some(Value::Int(n)) => (*n).max(1) as usize - 1,
                    _ => {
                        failed.push(Value::Str(format!("edit {}: missing start_line", idx)));
                        continue;
                    }
                };
                let end_line = match record.get("end_line") {
                    Some(Value::Int(n)) => (*n).max(1) as usize - 1,
                    _ => start_line,
                };

                if start_line < lines.len() {
                    let end = end_line.min(lines.len() - 1);
                    let deleted_count = end - start_line + 1;
                    lines.drain(start_line..=end);

                    let mut result = BTreeMap::new();
                    result.insert("op".to_string(), Value::Str("delete_range".to_string()));
                    result.insert(
                        "start_line".to_string(),
                        Value::Int((start_line + 1) as i64),
                    );
                    result.insert(
                        "lines_deleted".to_string(),
                        Value::Int(deleted_count as i64),
                    );
                    applied.push(Value::Record(result));
                } else {
                    failed.push(Value::Str(format!(
                        "edit {}: line {} out of range",
                        idx,
                        start_line + 1
                    )));
                }
            }
            _ => {
                failed.push(Value::Str(format!(
                    "edit {}: unknown operation '{}'",
                    idx, op
                )));
            }
        }
    }

    // Write back
    let mut new_content = lines.join("\n");
    if !new_content.is_empty() && !new_content.ends_with('\n') {
        new_content.push('\n');
    }

    let temp_path = format!("{}.aether_tmp", path);
    fs::write(&temp_path, &new_content)?;
    fs::rename(&temp_path, &path)?;

    let mut result = BTreeMap::new();
    result.insert("path".to_string(), Value::Str(path));
    result.insert("applied".to_string(), Value::Array(applied.clone()));
    result.insert("failed".to_string(), Value::Array(failed.clone()));
    result.insert("success".to_string(), Value::Bool(failed.is_empty()));
    result.insert(
        "edits_applied".to_string(),
        Value::Int(applied.len() as i64),
    );
    result.insert("edits_failed".to_string(), Value::Int(failed.len() as i64));
    result.insert("final_lines".to_string(), Value::Int(lines.len() as i64));

    Ok(Value::Record(result))
}

/// file_diff(path1, path2) - Compare two files and return differences
fn bi_file_diff(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    if args.len() < 2 {
        return Err(anyhow!("file_diff requires two file paths"));
    }

    let path1 = match &args[0] {
        Value::Str(s) => s.clone(),
        _ => return Err(anyhow!("file_diff: first path must be a string")),
    };

    let path2 = match &args[1] {
        Value::Str(s) => s.clone(),
        _ => return Err(anyhow!("file_diff: second path must be a string")),
    };

    let content1 = fs::read_to_string(&path1)
        .with_context(|| format!("file_diff: failed to read '{}'", path1))?;
    let content2 = fs::read_to_string(&path2)
        .with_context(|| format!("file_diff: failed to read '{}'", path2))?;

    let lines1: Vec<&str> = content1.lines().collect();
    let lines2: Vec<&str> = content2.lines().collect();

    let mut diffs = Vec::new();
    let max_lines = lines1.len().max(lines2.len());

    for i in 0..max_lines {
        let line1 = lines1.get(i);
        let line2 = lines2.get(i);

        match (line1, line2) {
            (Some(l1), Some(l2)) if l1 != l2 => {
                let mut diff = BTreeMap::new();
                diff.insert("line".to_string(), Value::Int((i + 1) as i64));
                diff.insert("type".to_string(), Value::Str("changed".to_string()));
                diff.insert("old".to_string(), Value::Str(l1.to_string()));
                diff.insert("new".to_string(), Value::Str(l2.to_string()));
                diffs.push(Value::Record(diff));
            }
            (Some(l1), None) => {
                let mut diff = BTreeMap::new();
                diff.insert("line".to_string(), Value::Int((i + 1) as i64));
                diff.insert("type".to_string(), Value::Str("deleted".to_string()));
                diff.insert("old".to_string(), Value::Str(l1.to_string()));
                diffs.push(Value::Record(diff));
            }
            (None, Some(l2)) => {
                let mut diff = BTreeMap::new();
                diff.insert("line".to_string(), Value::Int((i + 1) as i64));
                diff.insert("type".to_string(), Value::Str("added".to_string()));
                diff.insert("new".to_string(), Value::Str(l2.to_string()));
                diffs.push(Value::Record(diff));
            }
            _ => {}
        }
    }

    let mut result = BTreeMap::new();
    result.insert("file1".to_string(), Value::Str(path1));
    result.insert("file2".to_string(), Value::Str(path2));
    result.insert("lines1".to_string(), Value::Int(lines1.len() as i64));
    result.insert("lines2".to_string(), Value::Int(lines2.len() as i64));
    result.insert("differences".to_string(), Value::Array(diffs.clone()));
    result.insert("diff_count".to_string(), Value::Int(diffs.len() as i64));
    result.insert("identical".to_string(), Value::Bool(diffs.is_empty()));

    Ok(Value::Record(result))
}
/// file_backup(path, [suffix]) - Create a backup copy of a file before editing
/// Usage: file_backup("config.txt")  -> creates config.txt.bak
/// Usage: file_backup("config.txt", ".backup")  -> creates config.txt.backup
pub fn bi_file_backup(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let path = match args.first().or(input.as_ref()) {
        Some(Value::Str(s)) => s.clone(),
        _ => return Err(anyhow!("file_backup requires a file path")),
    };

    let suffix = match args.get(1) {
        Some(Value::Str(s)) => s.clone(),
        _ => ".bak".to_string(),
    };

    let backup_path = format!("{}{}", path, suffix);

    if !std::path::Path::new(&path).exists() {
        return Err(anyhow!(
            "file_backup: source file '{}' does not exist",
            path
        ));
    }

    let bytes_copied = fs::copy(&path, &backup_path).with_context(|| {
        format!(
            "file_backup: failed to copy '{}' to '{}'",
            path, backup_path
        )
    })?;

    let mut result = BTreeMap::new();
    result.insert("path".to_string(), Value::Str(path));
    result.insert("backup".to_string(), Value::Str(backup_path));
    result.insert("bytes".to_string(), Value::Int(bytes_copied as i64));
    result.insert("success".to_string(), Value::Bool(true));

    Ok(Value::Record(result))
}

/// file_copy(source, dest) - Copy a file or directory
pub fn bi_file_copy(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    if args.len() < 2 {
        return Err(anyhow!("file_copy requires source and destination paths"));
    }

    let source = match &args[0] {
        Value::Str(s) => s.clone(),
        _ => return Err(anyhow!("file_copy: source must be a string")),
    };

    let dest = match &args[1] {
        Value::Str(s) => s.clone(),
        _ => return Err(anyhow!("file_copy: destination must be a string")),
    };

    let source_path = std::path::Path::new(&source);

    if !source_path.exists() {
        return Err(anyhow!("file_copy: source '{}' does not exist", source));
    }

    let bytes_copied = if source_path.is_dir() {
        copy_dir_recursive(&source, &dest)?
    } else {
        fs::copy(&source, &dest)
            .with_context(|| format!("file_copy: failed to copy '{}' to '{}'", source, dest))?
    };

    let mut result = BTreeMap::new();
    result.insert("source".to_string(), Value::Str(source));
    result.insert("dest".to_string(), Value::Str(dest));
    result.insert("bytes".to_string(), Value::Int(bytes_copied as i64));
    result.insert("success".to_string(), Value::Bool(true));

    Ok(Value::Record(result))
}

fn copy_dir_recursive(src: &str, dst: &str) -> Result<u64> {
    let src_path = std::path::Path::new(src);
    let dst_path = std::path::Path::new(dst);

    fs::create_dir_all(dst_path)?;

    let mut total_bytes = 0u64;

    for entry in WalkDir::new(src_path).min_depth(1) {
        let entry = entry?;
        let src_file = entry.path();
        let relative = src_file.strip_prefix(src_path)?;
        let dst_file = dst_path.join(relative);

        if entry.file_type().is_dir() {
            fs::create_dir_all(&dst_file)?;
        } else {
            if let Some(parent) = dst_file.parent() {
                fs::create_dir_all(parent)?;
            }
            total_bytes += fs::copy(src_file, &dst_file)?;
        }
    }

    Ok(total_bytes)
}

/// file_move(source, dest) - Move/rename a file or directory
pub fn bi_file_move(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    if args.len() < 2 {
        return Err(anyhow!("file_move requires source and destination paths"));
    }

    let source = match &args[0] {
        Value::Str(s) => s.clone(),
        _ => return Err(anyhow!("file_move: source must be a string")),
    };

    let dest = match &args[1] {
        Value::Str(s) => s.clone(),
        _ => return Err(anyhow!("file_move: destination must be a string")),
    };

    if !std::path::Path::new(&source).exists() {
        return Err(anyhow!("file_move: source '{}' does not exist", source));
    }

    let metadata = fs::metadata(&source)?;
    let bytes = metadata.len();

    fs::rename(&source, &dest)
        .with_context(|| format!("file_move: failed to move '{}' to '{}'", source, dest))?;

    let mut result = BTreeMap::new();
    result.insert("source".to_string(), Value::Str(source));
    result.insert("dest".to_string(), Value::Str(dest));
    result.insert("bytes".to_string(), Value::Int(bytes as i64));
    result.insert("success".to_string(), Value::Bool(true));

    Ok(Value::Record(result))
}

/// file_exists(path) - Check if a file or directory exists
pub fn bi_file_exists(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let path = match args.first().or(input.as_ref()) {
        Some(Value::Str(s)) => s.clone(),
        _ => return Err(anyhow!("file_exists requires a path")),
    };

    let exists = std::path::Path::new(&path).exists();
    let is_file = std::path::Path::new(&path).is_file();
    let is_dir = std::path::Path::new(&path).is_dir();

    let mut result = BTreeMap::new();
    result.insert("path".to_string(), Value::Str(path));
    result.insert("exists".to_string(), Value::Bool(exists));
    result.insert("is_file".to_string(), Value::Bool(is_file));
    result.insert("is_dir".to_string(), Value::Bool(is_dir));

    Ok(Value::Record(result))
}

/// file_mkdir(path) - Create a directory (and parents if needed)
pub fn bi_file_mkdir(args: Vec<Value>, input: Option<Value>) -> Result<Value> {
    let path = match args.first().or(input.as_ref()) {
        Some(Value::Str(s)) => s.clone(),
        _ => return Err(anyhow!("file_mkdir requires a path")),
    };

    let already_exists = std::path::Path::new(&path).exists();

    fs::create_dir_all(&path)
        .with_context(|| format!("file_mkdir: failed to create '{}'", path))?;

    let mut result = BTreeMap::new();
    result.insert("path".to_string(), Value::Str(path));
    result.insert("created".to_string(), Value::Bool(!already_exists));
    result.insert("success".to_string(), Value::Bool(true));

    Ok(Value::Record(result))
}

// ===================== A2A (Agent-to-Agent) Protocol =====================

lazy_static::lazy_static! {
    /// A2A agent registry - maps agent names to their connection info
    static ref A2A_REGISTRY: std::sync::RwLock<BTreeMap<String, BTreeMap<String, Value>>> = {
        std::sync::RwLock::new(BTreeMap::new())
    };

    /// A2A message queue - pending messages for each agent
    static ref A2A_MESSAGES: std::sync::RwLock<BTreeMap<String, Vec<Value>>> = {
        std::sync::RwLock::new(BTreeMap::new())
    };
}

/// a2a.send(target, message) - Send a message to another agent
fn bi_a2a_send(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    if args.len() < 2 {
        return Err(anyhow!("a2a.send: requires target and message arguments"));
    }
    let target = args[0]
        .as_str()
        .context("a2a.send: target must be a string")?;
    let message = args[1].clone();

    let registry = A2A_REGISTRY.read().unwrap();
    if !registry.contains_key(target) {
        return Err(anyhow!(
            "a2a.send: agent '{}' not found in registry",
            target
        ));
    }
    drop(registry);

    let mut messages = A2A_MESSAGES.write().unwrap();
    messages
        .entry(target.to_string())
        .or_default()
        .push(message);

    let mut result = BTreeMap::new();
    result.insert("sent".to_string(), Value::Bool(true));
    result.insert("target".to_string(), Value::Str(target.to_string()));
    Ok(Value::Record(result))
}

/// a2a.receive(agent_name?) - Receive pending messages
fn bi_a2a_receive(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let agent_name = args
        .first()
        .and_then(|v| v.as_str().ok())
        .map(|s| s.to_string())
        .unwrap_or_else(|| "default".to_string());
    let mut messages = A2A_MESSAGES.write().unwrap();
    let pending = messages.remove(&agent_name).unwrap_or_default();
    Ok(Value::Array(pending))
}

/// a2a.broadcast(message) - Broadcast to all agents
fn bi_a2a_broadcast(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    if args.is_empty() {
        return Err(anyhow!("a2a.broadcast: requires a message"));
    }
    let message = args[0].clone();
    let registry = A2A_REGISTRY.read().unwrap();
    let agents: Vec<String> = registry.keys().cloned().collect();
    drop(registry);
    let mut messages = A2A_MESSAGES.write().unwrap();
    for agent in &agents {
        messages
            .entry(agent.clone())
            .or_default()
            .push(message.clone());
    }
    let mut result = BTreeMap::new();
    result.insert("broadcast".to_string(), Value::Bool(true));
    result.insert("recipients".to_string(), Value::Int(agents.len() as i64));
    Ok(Value::Record(result))
}

/// a2a.discover() - Discover available agents
fn bi_a2a_discover(_args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let registry = A2A_REGISTRY.read().unwrap();
    let agents: Vec<Value> = registry
        .iter()
        .map(|(name, info)| {
            let mut agent = info.clone();
            agent.insert("name".to_string(), Value::Str(name.clone()));
            Value::Record(agent)
        })
        .collect();
    Ok(Value::Array(agents))
}

/// a2a.register(name, info?) - Register an agent
fn bi_a2a_register(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    if args.is_empty() {
        return Err(anyhow!("a2a.register: requires agent name"));
    }
    let name = args[0]
        .as_str()
        .context("a2a.register: name must be a string")?;
    let info = args
        .get(1)
        .and_then(|v| v.as_record().ok())
        .cloned()
        .unwrap_or_default();
    let mut registry = A2A_REGISTRY.write().unwrap();
    registry.insert(name.to_string(), info);
    let mut result = BTreeMap::new();
    result.insert("registered".to_string(), Value::Bool(true));
    result.insert("name".to_string(), Value::Str(name.to_string()));
    Ok(Value::Record(result))
}

/// a2a.unregister(name) - Unregister an agent
fn bi_a2a_unregister(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    if args.is_empty() {
        return Err(anyhow!("a2a.unregister: requires agent name"));
    }
    let name = args[0]
        .as_str()
        .context("a2a.unregister: name must be a string")?;
    let mut registry = A2A_REGISTRY.write().unwrap();
    let removed = registry.remove(name).is_some();
    let mut messages = A2A_MESSAGES.write().unwrap();
    messages.remove(name);
    let mut result = BTreeMap::new();
    result.insert("unregistered".to_string(), Value::Bool(removed));
    result.insert("name".to_string(), Value::Str(name.to_string()));
    Ok(Value::Record(result))
}

/// a2a.status() - Get A2A subsystem status
fn bi_a2a_status(_args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let registry = A2A_REGISTRY.read().unwrap();
    let messages = A2A_MESSAGES.read().unwrap();
    let pending_count: usize = messages.values().map(|v| v.len()).sum();
    let mut result = BTreeMap::new();
    result.insert("active".to_string(), Value::Bool(true));
    result.insert("agents".to_string(), Value::Int(registry.len() as i64));
    result.insert(
        "pending_messages".to_string(),
        Value::Int(pending_count as i64),
    );
    Ok(Value::Record(result))
}

/// a2a.agents() - List all registered agents
fn bi_a2a_agents(_args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    let registry = A2A_REGISTRY.read().unwrap();
    let agents: Vec<Value> = registry
        .keys()
        .map(|name| Value::Str(name.clone()))
        .collect();
    Ok(Value::Array(agents))
}

// ===================== NANDA (Consensus) Protocol =====================

lazy_static::lazy_static! {
    static ref NANDA_PROPOSALS: std::sync::RwLock<BTreeMap<String, BTreeMap<String, Value>>> = {
        std::sync::RwLock::new(BTreeMap::new())
    };
    static ref NANDA_VOTES: std::sync::RwLock<BTreeMap<String, Vec<(String, bool)>>> = {
        std::sync::RwLock::new(BTreeMap::new())
    };
}

fn nanda_uuid() -> String {
    use rand::Rng;
    let mut rng = rand::thread_rng();
    let bytes: [u8; 16] = rng.gen();
    format!(
        "{:08x}-{:04x}-4{:03x}-{:04x}-{:012x}",
        u32::from_be_bytes([bytes[0], bytes[1], bytes[2], bytes[3]]),
        u16::from_be_bytes([bytes[4], bytes[5]]),
        u16::from_be_bytes([bytes[6], bytes[7]]) & 0x0fff,
        (u16::from_be_bytes([bytes[8], bytes[9]]) & 0x3fff) | 0x8000,
        u64::from_be_bytes([
            0, 0, bytes[10], bytes[11], bytes[12], bytes[13], bytes[14], bytes[15]
        ])
    )
}

/// nanda.propose(name, data) - Create a consensus proposal
fn bi_nanda_propose(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    if args.len() < 2 {
        return Err(anyhow!("nanda.propose: requires name and data arguments"));
    }
    let name = args[0]
        .as_str()
        .context("nanda.propose: name must be a string")?;
    let data = args[1]
        .as_record()
        .context("nanda.propose: data must be a record")?;
    let proposal_id = format!("prop_{}", nanda_uuid());
    let threshold = data
        .get("threshold")
        .and_then(|v| v.as_float().ok())
        .unwrap_or(0.5);
    let mut proposal = data.clone();
    proposal.insert("id".to_string(), Value::Str(proposal_id.clone()));
    proposal.insert("name".to_string(), Value::Str(name.to_string()));
    proposal.insert("threshold".to_string(), Value::Float(threshold));
    proposal.insert("status".to_string(), Value::Str("pending".to_string()));
    let mut proposals = NANDA_PROPOSALS.write().unwrap();
    proposals.insert(proposal_id.clone(), proposal.clone());
    Ok(Value::Record(proposal))
}

/// nanda.vote(proposal_id, approve) - Vote on a proposal
fn bi_nanda_vote(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    if args.len() < 2 {
        return Err(anyhow!(
            "nanda.vote: requires proposal_id and approve arguments"
        ));
    }
    let proposal_id = args[0]
        .as_str()
        .context("nanda.vote: proposal_id must be a string")?;
    let approve = args[1]
        .as_bool()
        .context("nanda.vote: approve must be a boolean")?;
    let proposals = NANDA_PROPOSALS.read().unwrap();
    if !proposals.contains_key(proposal_id) {
        return Err(anyhow!("nanda.vote: proposal '{}' not found", proposal_id));
    }
    drop(proposals);
    let voter = format!("voter_{}", rand::random::<u32>() % 1000);
    let mut votes = NANDA_VOTES.write().unwrap();
    votes
        .entry(proposal_id.to_string())
        .or_default()
        .push((voter.clone(), approve));
    let mut result = BTreeMap::new();
    result.insert("voted".to_string(), Value::Bool(true));
    result.insert(
        "proposal_id".to_string(),
        Value::Str(proposal_id.to_string()),
    );
    result.insert("voter".to_string(), Value::Str(voter));
    result.insert("approve".to_string(), Value::Bool(approve));
    Ok(Value::Record(result))
}

/// nanda.commit(proposal_id) - Commit a proposal if consensus reached
fn bi_nanda_commit(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    if args.is_empty() {
        return Err(anyhow!("nanda.commit: requires proposal_id"));
    }
    let proposal_id = args[0]
        .as_str()
        .context("nanda.commit: proposal_id must be a string")?;
    let mut proposals = NANDA_PROPOSALS.write().unwrap();
    let proposal = proposals
        .get_mut(proposal_id)
        .ok_or_else(|| anyhow!("nanda.commit: proposal '{}' not found", proposal_id))?;
    let threshold = proposal
        .get("threshold")
        .and_then(|v| v.as_float().ok())
        .unwrap_or(0.5);
    let votes = NANDA_VOTES.read().unwrap();
    let proposal_votes = votes.get(proposal_id).map(|v| v.as_slice()).unwrap_or(&[]);
    let total = proposal_votes.len();
    let approvals = proposal_votes.iter().filter(|(_, v)| *v).count();
    let approval_ratio = if total > 0 {
        approvals as f64 / total as f64
    } else {
        0.0
    };
    if approval_ratio >= threshold {
        proposal.insert("status".to_string(), Value::Str("committed".to_string()));
        let mut result = BTreeMap::new();
        result.insert("committed".to_string(), Value::Bool(true));
        result.insert(
            "proposal_id".to_string(),
            Value::Str(proposal_id.to_string()),
        );
        result.insert("approval_ratio".to_string(), Value::Float(approval_ratio));
        Ok(Value::Record(result))
    } else {
        Err(anyhow!(
            "nanda.commit: consensus not reached ({}% < {}%)",
            (approval_ratio * 100.0) as i64,
            (threshold * 100.0) as i64
        ))
    }
}

/// nanda.abort(proposal_id) - Abort a proposal
fn bi_nanda_abort(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    if args.is_empty() {
        return Err(anyhow!("nanda.abort: requires proposal_id"));
    }
    let proposal_id = args[0]
        .as_str()
        .context("nanda.abort: proposal_id must be a string")?;
    let mut proposals = NANDA_PROPOSALS.write().unwrap();
    let proposal = proposals
        .get_mut(proposal_id)
        .ok_or_else(|| anyhow!("nanda.abort: proposal '{}' not found", proposal_id))?;
    proposal.insert("status".to_string(), Value::Str("aborted".to_string()));
    let mut result = BTreeMap::new();
    result.insert("aborted".to_string(), Value::Bool(true));
    result.insert(
        "proposal_id".to_string(),
        Value::Str(proposal_id.to_string()),
    );
    Ok(Value::Record(result))
}

/// nanda.status(proposal_id?) - Get proposal status
fn bi_nanda_status(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    if let Some(proposal_id) = args.first().and_then(|v| v.as_str().ok()) {
        let proposals = NANDA_PROPOSALS.read().unwrap();
        let proposal = proposals
            .get(proposal_id)
            .ok_or_else(|| anyhow!("nanda.status: proposal '{}' not found", proposal_id))?;
        Ok(Value::Record(proposal.clone()))
    } else {
        let proposals = NANDA_PROPOSALS.read().unwrap();
        let summary: Vec<Value> = proposals
            .iter()
            .map(|(_, p)| Value::Record(p.clone()))
            .collect();
        Ok(Value::Array(summary))
    }
}

/// nanda.consensus(proposal_id) - Check if consensus has been reached
fn bi_nanda_consensus(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    if args.is_empty() {
        return Err(anyhow!("nanda.consensus: requires proposal_id"));
    }
    let proposal_id = args[0]
        .as_str()
        .context("nanda.consensus: proposal_id must be a string")?;
    let proposals = NANDA_PROPOSALS.read().unwrap();
    let proposal = proposals
        .get(proposal_id)
        .ok_or_else(|| anyhow!("nanda.consensus: proposal '{}' not found", proposal_id))?;
    let threshold = proposal
        .get("threshold")
        .and_then(|v| v.as_float().ok())
        .unwrap_or(0.5);
    let votes = NANDA_VOTES.read().unwrap();
    let proposal_votes = votes.get(proposal_id).map(|v| v.as_slice()).unwrap_or(&[]);
    let total = proposal_votes.len();
    let approvals = proposal_votes.iter().filter(|(_, v)| *v).count();
    let approval_ratio = if total > 0 {
        approvals as f64 / total as f64
    } else {
        0.0
    };
    let mut result = BTreeMap::new();
    result.insert(
        "reached".to_string(),
        Value::Bool(approval_ratio >= threshold),
    );
    result.insert("approval_ratio".to_string(), Value::Float(approval_ratio));
    result.insert("threshold".to_string(), Value::Float(threshold));
    result.insert("total_votes".to_string(), Value::Int(total as i64));
    result.insert("approvals".to_string(), Value::Int(approvals as i64));
    Ok(Value::Record(result))
}

/// nanda.quorum(proposal_id) - Get quorum status
fn bi_nanda_quorum(args: Vec<Value>, _input: Option<Value>) -> Result<Value> {
    if args.is_empty() {
        return Err(anyhow!("nanda.quorum: requires proposal_id"));
    }
    let proposal_id = args[0]
        .as_str()
        .context("nanda.quorum: proposal_id must be a string")?;
    let proposals = NANDA_PROPOSALS.read().unwrap();
    if !proposals.contains_key(proposal_id) {
        return Err(anyhow!(
            "nanda.quorum: proposal '{}' not found",
            proposal_id
        ));
    }
    let registry = A2A_REGISTRY.read().unwrap();
    let total_agents = registry.len().max(1);
    let votes = NANDA_VOTES.read().unwrap();
    let proposal_votes = votes.get(proposal_id).map(|v| v.len()).unwrap_or(0);
    let quorum_ratio = proposal_votes as f64 / total_agents as f64;
    let quorum_reached = quorum_ratio >= 0.5;
    let mut result = BTreeMap::new();
    result.insert("quorum_reached".to_string(), Value::Bool(quorum_reached));
    result.insert("participation".to_string(), Value::Float(quorum_ratio));
    result.insert("votes_cast".to_string(), Value::Int(proposal_votes as i64));
    result.insert("total_agents".to_string(), Value::Int(total_agents as i64));
    Ok(Value::Record(result))
}

