    let detach = args
        .first()
        .map(|v| matches!(v, Value::Bool(true)))
        .unwrap_or(true);
    if detach {
        cmd_args.push("-d");
    }
    // Optional compose file
    let file_arg;
    if let Some(Value::Str(f)) = args.get(1) {
        file_arg = f.clone();
        cmd_args.insert(1, "-f");
        cmd_args.insert(2, &file_arg);
    }
    let text = container_run_cmd("docker", &cmd_args)?;
    Ok(Value::Str(text))
