    let install_path = require_str(&args, 1, "wsl.import")?;
    let tarball = require_str(&args, 2, "wsl.import")?;
    vm_run_cmd("wsl", &["--import", &name, &install_path, &tarball])?;
    Ok(Value::Str(format!("WSL distro '{}' imported from '{}'", name, tarball)))
